// =============================================================
// WIDGET KOMMO: TICKET PROMEDIO DE VENTAS GANADAS
// =============================================================
// Logica:
//   - Suma el campo "Presupuesto" (nativo: lead.price) de leads ganados
//   - Divide entre el total de leads ganados que tienen precio valido
// =============================================================

// CONFIGURACION
const PIPELINE_VENTAS = 12677012;      // Ventas principal
const PIPELINE_RECURRENTES = 12676956; // Clientes Recurrentes
const STAGE_WON_ID = 142;              // VENTA GANADA

// Si en el futuro quieres usar un campo personalizado en lugar del nativo,
// pon aqui su field_id numerico. Si lo dejas en null, usa lead.price (nativo).
const FIELD_PRESUPUESTO_ID = null; // ej: 1046505 para "Valor Cotizado"
// FIN CONFIGURACION

// Aplanar todas las paginas del HTTP Request
const leads = items.flatMap(i => i.json._embedded?.leads ?? []);

// Helper: convierte un valor (string/number) a numero limpio
// Soporta formatos: "1234.56", "1.234,56", "$1,234.56", "()", etc.
function parsePrecio(valor) {
  if (valor === null || valor === undefined) return null;
  if (typeof valor === 'number') {
    return Number.isFinite(valor) && valor > 0 ? valor : null;
  }
  const s = String(valor).trim();
  if (s === '') return null;
  // Limpiar simbolos de moneda y espacios
  const limpio = s.replace(/[$\s]/g, '');
  // Descartar valores claramente invalidos
  if (limpio === '' || limpio === '()' || limpio === '0' || limpio === '0.00') return null;

  const tieneComa = limpio.includes(',');
  const tienePunto = limpio.includes('.');
  let n;
  if (tieneComa && tienePunto) {
    // Formato latino "1.234,56" o anglo "1,234.56"
    if (limpio.lastIndexOf(',') > limpio.lastIndexOf('.')) {
      n = Number(limpio.split('.').join('').replace(',', '.'));
    } else {
      n = Number(limpio.split(',').join(''));
    }
  } else if (tieneComa) {
    const partes = limpio.split(',');
    const esMiles = partes.slice(1).every(p => p.length === 3) && partes[0].length <= 3;
    n = esMiles ? Number(partes.join('')) : Number(limpio.replace(',', '.'));
  } else {
    n = Number(limpio);
  }
  return Number.isFinite(n) && n > 0 ? n : null;
}

// Helper: obtiene el presupuesto de un lead
function obtenerPresupuesto(lead) {
  // 1) Campo personalizado (si esta configurado)
  if (FIELD_PRESUPUESTO_ID !== null) {
    const field = lead.custom_fields_values?.find(
      f => f.field_id === FIELD_PRESUPUESTO_ID
    );
    const parsed = parsePrecio(field?.values?.[0]?.value);
    if (parsed !== null) return parsed;
  }
  // 2) Campo nativo "Presupuesto" (lead.price)
  return parsePrecio(lead.price);
}

let suma = 0;
let countWon = 0;
let sinPrecio = 0;
let preciosValidos = 0;

for (const lead of leads) {
  // Solo de nuestros pipelines
  if (lead.pipeline_id !== PIPELINE_VENTAS && lead.pipeline_id !== PIPELINE_RECURRENTES) continue;
  // Solo ganados
  if (lead.status_id !== STAGE_WON_ID) continue;

  countWon++;

  const precio = obtenerPresupuesto(lead);
  if (precio === null) {
    sinPrecio++;
    continue;
  }

  suma += precio;
  preciosValidos++;
}

// Promedio sobre los que SI tienen precio (evita sesgo a la baja)
const promedio = preciosValidos > 0 ? suma / preciosValidos : 0;

const formatear = n => '$' + n.toLocaleString('es-EC', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
});

// Logs de debug (aparecen en la consola del nodo Code en n8n)
console.log(`Total leads ganados: ${countWon}`);
console.log(`Con precio valido: ${preciosValidos}`);
console.log(`Sin precio: ${sinPrecio}`);
console.log(`Suma total: ${suma}`);
console.log(`Promedio: ${promedio}`);

return [{
  json: {
    text_main: formatear(promedio),
    text_sub: `${countWon} ventas ganadas`,
    raw_sum: suma,
    raw_won: countWon,
    raw_con_precio: preciosValidos,
    raw_sin_precio: sinPrecio,
    raw_avg: promedio
  }
}];
